 function frame(now){if(closed)return;const delta=Math.min(.1,(now-last)/1000);last=now;if(!paused){const x=stick.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),z=stick.z+(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),input={x:-x*Math.cos(yaw)+z*Math.sin(yaw),z:z*Math.cos(yaw)+x*Math.sin(yaw),run:runEnabled||keys.has('ShiftLeft')||keys.has('ShiftRight')};let remaining=delta;while(remaining>0){const dt=Math.min(1/60,remaining);state.update(dt,input);remaining-=dt;}events();music(delta);saveClock+=delta;if(saveClock>10){saveClock=0;save();}slow=delta>.04?slow+delta:Math.max(0,slow-delta*.2);if(slow>3&&ratio>.65){ratio=Math.max(.65,ratio-.2);renderer.setPixelRatio(ratio);renderer.shadowMap.enabled=false;slow=0;resize();}}draw(paused?1/60:delta);raf=requestAnimationFrame(frame);}
